459	func (s *service) routeUtilizationEvidence(provider, serverInstance, endpoint, model string) RouteUtilizationState {
460		if s == nil {
461			return RouteUtilizationState{}
462		}
463		store := s.routeUtilizationStore()
464		if store == nil {
465			return RouteUtilizationState{}
466		}
467		keyProvider := strings.TrimSpace(provider)
468		keyServerInstance := strings.TrimSpace(serverInstance)
469		keyEndpoint := strings.TrimSpace(endpoint)
470		if base, ep, ok := splitEndpointProviderRef(keyProvider); ok {
471			keyProvider = base
472			if keyEndpoint == "" {
473				keyEndpoint = ep
474			}
475		}
476		if keyServerInstance == "" {
477			keyServerInstance = keyEndpoint
478		}
479		sample, ok := store.Sample(keyProvider, keyServerInstance, model)
480		if !ok && keyEndpoint != "" && keyEndpoint != keyServerInstance {
481			sample, ok = store.Sample(keyProvider, keyEndpoint, model)
482		}
483		if !ok {
484			return RouteUtilizationState{}
485		}
486		return routeUtilizationStateFromSample(sample)
487	}
