489	func routeUtilizationStateFromSample(sample utilization.EndpointUtilization) RouteUtilizationState {
490		out := RouteUtilizationState{
491			Source:     string(sample.Source),
492			Freshness:  string(sample.Freshness),
493			ObservedAt: sample.ObservedAt,
494		}
495		if sample.ActiveRequests != nil {
496			out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
497		}
498		if sample.QueuedRequests != nil {
499			out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
500		}
501		if sample.MaxConcurrency != nil {
502			out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
503		}
504		if sample.CacheUsage != nil {
505			v := *sample.CacheUsage
506			out.CachePressure = &v
507		}
508		if out.CachePressure == nil && sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
509			total := 0
510			if sample.ActiveRequests != nil {
511				total += *sample.ActiveRequests
512			}
513			if sample.QueuedRequests != nil {
514				total += *sample.QueuedRequests
515			}
516			pressure := float64(total) / float64(*sample.MaxConcurrency)
517			out.CachePressure = &pressure
518		}
519		return out
520	}
