530	// capabilityScoreForCostClass maps the harness cost class to a coarse
531	// numeric capability proxy. Mirrors the engine's costClassRank ordering
532	// (more expensive ≈ more capable) for reporting purposes only.
533	func capabilityScoreForCostClass(class string) float64 {
534		switch class {
535		case "local":
536			return 0
537		case "cheap":
538			return 1
539		case "medium", "":
540			return 2
541		case "expensive":
542			return 3
543		case "experimental":
544			return -1
545		default:
546			return 0
547		}
548	}
