550	// escalatePolicyLadder walks routing.PolicyEscalationLadder when Resolve
551	// returns a "no eligible candidate" error and the request's policy is in
552	// the ladder. Returns (true, decision, nil) when a higher tier resolves to
553	// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
554	// the entire remaining ladder is also empty. Returns (false, _, _) when
555	// escalation does not apply (hard pin error, policy not in ladder, etc.).
556	func escalatePolicyLadder(req routing.Request, in routing.Inputs, origErr error, displayPolicy string) (bool, *routing.Decision, error) {
557		return routehealth.EscalatePolicyLadder(req, in, origErr, displayPolicy, shouldEscalateOnError)
558	}
559	
560	// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
561	// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
562	// ErrPolicyRequirementUnsatisfied) are surfaced as-is — escalating past an explicit
563	// pin would silently change the caller's intent.
564	func shouldEscalateOnError(err error) bool {
565		var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
566		if errors.As(err, &modelConstraintAmbiguous) {
567			return false
568		}
569		var modelConstraintNoMatch *ErrModelConstraintNoMatch
570		if errors.As(err, &modelConstraintNoMatch) {
571			return false
572		}
573		var modelErr *routing.ErrHarnessModelIncompatible
574		if errors.As(err, &modelErr) {
575			return false
576		}
577		var pinErr *routing.ErrUnsatisfiablePin
578		if errors.As(err, &pinErr) {
579			return false
580		}
581		var policyErr *routing.ErrPolicyRequirementUnsatisfied
582		if errors.As(err, &policyErr) {
583			return false
584		}
585		return routehealth.ShouldEscalateOnError(err)
586	}
587	
588	func publicRoutingError(err error, candidates []RouteCandidate, requestedPolicy ...string) error {
589		displayPolicy := func(policy string) string {
590			if len(requestedPolicy) > 0 && requestedPolicy[0] != "" {
591				return requestedPolicy[0]
592			}
593			return policy
594		}
595		var modelErr *routing.ErrHarnessModelIncompatible
596		if errors.As(err, &modelErr) {
597			return withRouteCandidates(&ErrHarnessModelIncompatible{
598				Harness:         modelErr.Harness,
599				Model:           modelErr.Model,
600				SupportedModels: append([]string(nil), modelErr.SupportedModels...),
601			}, candidates)
602		}
603		var policyErr *routing.ErrPolicyRequirementUnsatisfied
604		if errors.As(err, &policyErr) {
605			return withRouteCandidates(&ErrPolicyRequirementUnsatisfied{
606				Policy:       displayPolicy(policyErr.Policy),
607				Requirement:  policyErr.Requirement,
608				AttemptedPin: policyErr.AttemptedPin,
609				Rejected:     policyErr.Rejected,
610			}, candidates)
611		}
612		var unknownPolicyErr *routing.ErrUnknownPolicy
613		if errors.As(err, &unknownPolicyErr) {
614			return withRouteCandidates(&ErrUnknownPolicy{
615				Policy: displayPolicy(unknownPolicyErr.Policy),
616			}, candidates)
617		}
618		var pinErr *routing.ErrUnsatisfiablePin
619		if errors.As(err, &pinErr) {
620			return withRouteCandidates(&ErrUnsatisfiablePin{
621				Pin:    pinErr.Pin,
622				Reason: pinErr.Reason,
623			}, candidates)
624		}
625		var noLiveErr *routing.ErrNoLiveProvider
626		if errors.As(err, &noLiveErr) {
627			return withRouteCandidates(&ErrNoLiveProvider{
628				PromptTokens:   noLiveErr.PromptTokens,
629				RequiresTools:  noLiveErr.RequiresTools,
630				StartingPolicy: displayPolicy(noLiveErr.StartingPolicy),
631			}, candidates)
632		}
633		var quotaErr *routing.ErrAllProvidersQuotaExhausted
634		if errors.As(err, &quotaErr) {
635			return withRouteCandidates(&NoViableProviderForNow{
636				RetryAfter:         quotaErr.RetryAfter,
637				ExhaustedProviders: append([]string(nil), quotaErr.ExhaustedProviders...),
638			}, candidates)
639		}
640		return withRouteCandidates(err, candidates)
641	}
642	
643	func withRouteCandidates(err error, candidates []RouteCandidate) error {
644		if err == nil || len(candidates) == 0 {
645			return err
646		}
647		return &routeDecisionError{
648			err:        err,
649			candidates: append([]RouteCandidate(nil), candidates...),
650		}
651	}
