905	// providerCooldownsFromSnapshotErrors walks snapshot.Sources and returns a map
906	// of providerName → failure-time for any provider whose most recent discovery
907	// attempt failed with a dial-class error within the cooldown window. The map
908	// feeds routing.Inputs.ProviderCooldowns so engine.go can hard-gate the
909	// candidate before any dispatch attempt.
910	//
911	// Source names are produced by endpointSourceName: they start with the
912	// provider name (optionally followed by "-<endpoint>-<hash>" or "-props").
913	// We match by prefix against the configured provider name set so a source
914	// name like "rg-bragi-club-3090-props" correctly maps to provider
915	// "rg-bragi-club-3090".
916	func providerCooldownsFromSnapshotErrors(snapshot modelsnapshot.ModelSnapshot, cfg ServiceConfigSource, now time.Time, ttl time.Duration) map[string]time.Time {
917		if len(snapshot.Sources) == 0 {
918			return nil
919		}
920		providerNames := []string{}
921		if cfg != nil {
922			providerNames = cfg.ProviderNames()
923		}
924		if len(providerNames) == 0 {
925			return nil
926		}
927		sources := make([]routehealth.SnapshotSource, 0, len(snapshot.Sources))
928		for name, meta := range snapshot.Sources {
929			sources = append(sources, routehealth.SnapshotSource{
930				Name:            name,
931				Error:           meta.Error,
932				LastRefreshedAt: meta.LastRefreshedAt,
933			})
934		}
935		return routehealth.ProviderCooldownsFromSnapshotErrors(sources, providerNames, now, ttl)
936	}
