945	func (s *service) snapshotProviderEntries(ctx context.Context, cat *modelcatalog.Catalog, snapshot modelsnapshot.ModelSnapshot) []routing.ProviderEntry {
946		if s == nil || s.opts.ServiceConfig == nil {
947			return nil
948		}
949		providerNames := s.opts.ServiceConfig.ProviderNames()
950		if len(providerNames) == 0 || len(snapshot.Models) == 0 {
951			return nil
952		}
953		grouped := make(map[snapshotProviderGroupKey][]modelsnapshot.KnownModel)
954		for _, row := range snapshot.Models {
955			harness := strings.TrimSpace(row.Harness)
956			if harness != "" && harness != "fiz" {
957				continue
958			}
959			providerName := strings.TrimSpace(row.Provider)
960			if providerName == "" {
961				continue
962			}
963			if _, ok := s.opts.ServiceConfig.Provider(providerName); !ok {
964				continue
965			}
966			key := snapshotProviderGroupKey{
967				Provider:        providerName,
968				EndpointName:    strings.TrimSpace(row.EndpointName),
969				EndpointBaseURL: strings.TrimSpace(row.EndpointBaseURL),
970				ServerInstance:  strings.TrimSpace(row.ServerInstance),
971			}
972			grouped[key] = append(grouped[key], row)
973		}
974		groupCountByProvider := make(map[string]int)
975		for key := range grouped {
976			groupCountByProvider[key.Provider]++
977		}
978		if len(grouped) == 0 {
979			return nil
980		}
981	
982		keys := make([]snapshotProviderGroupKey, 0, len(grouped))
983		for key := range grouped {
984			keys = append(keys, key)
985		}
986		sort.Slice(keys, func(i, j int) bool {
987			if keys[i].Provider != keys[j].Provider {
988				return keys[i].Provider < keys[j].Provider
989			}
990			if keys[i].EndpointName != keys[j].EndpointName {
991				return keys[i].EndpointName < keys[j].EndpointName
992			}
993			if keys[i].EndpointBaseURL != keys[j].EndpointBaseURL {
994				return keys[i].EndpointBaseURL < keys[j].EndpointBaseURL
995			}
996			return keys[i].ServerInstance < keys[j].ServerInstance
997		})
998	
999		var entries []routing.ProviderEntry
1000		for _, key := range keys {
1001			pcfg, ok := s.opts.ServiceConfig.Provider(key.Provider)
1002			if !ok || pcfg.ConfigError != "" {
1003				continue
1004			}
1005			rows := append([]modelsnapshot.KnownModel(nil), grouped[key]...)
1006			sort.Slice(rows, func(i, j int) bool {
1007				if rows[i].EndpointName != rows[j].EndpointName {
1008					return rows[i].EndpointName < rows[j].EndpointName
1009				}
1010				if rows[i].EndpointBaseURL != rows[j].EndpointBaseURL {
1011					return rows[i].EndpointBaseURL < rows[j].EndpointBaseURL
1012				}
1013				if rows[i].ServerInstance != rows[j].ServerInstance {
1014					return rows[i].ServerInstance < rows[j].ServerInstance
1015				}
1016				return rows[i].ID < rows[j].ID
1017			})
1018			discoveredIDs := snapshotModelIDs(rows)
1019			if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
1020				discoveredIDs = appendUniqueModelIDs(discoveredIDs, defaultModel)
1021			}
1022			ctxWindows, ctxSources := snapshotProviderContextWindows(ctx, pcfg, cat, rows, discoveredIDs)
1023			endpointName := snapshotEndpointName(pcfg, key)
1024			routeName := key.Provider
1025			if groupCountByProvider[key.Provider] > 1 {
1026				switch {
1027				case endpointName != "":
1028					routeName = endpointProviderRef(key.Provider, endpointName)
1029				case key.ServerInstance != "":
1030					routeName = endpointProviderRef(key.Provider, key.ServerInstance)
1031				case key.EndpointBaseURL != "":
1032					routeName = endpointProviderRef(key.Provider, key.EndpointBaseURL)
1033				}
1034			}
1035			baseURL := key.EndpointBaseURL
1036			if baseURL == "" {
1037				baseURL = pcfg.BaseURL
1038			}
1039			serverInstance := key.ServerInstance
1040			if serverInstance == "" {
1041				serverInstance = pcfg.ServerInstance
1042			}
1043			serverInstance = serverinstance.Normalize(baseURL, serverInstance)
1044			entry := routing.ProviderEntry{
1045				Name:                      routeName,
1046				BaseURL:                   baseURL,
1047				ServerInstance:            serverInstance,
1048				EndpointName:              endpointName,
1049				EndpointBaseURL:           baseURL,
1050				DefaultModel:              pcfg.Model,
1051				Billing:                   pcfg.Billing,
1052				CostClass:                 providerRoutingCostClass(pcfg.Type),
1053				DiscoveredIDs:             discoveredIDs,
1054				DiscoveryAttempted:        true,
1055				ContextWindows:            ctxWindows,
1056				ContextWindowSources:      ctxSources,
1057				ContextWindow:             pcfg.ContextWindow,
1058				ContextWindowSource:       contextWindowSourceForProviderConfig(pcfg),
1059				SupportsTools:             providerSupportsTools(cat, pcfg.Model, discoveredIDs),
1060				ExcludeFromDefaultRouting: pcfg.IncludeByDefaultSet && !pcfg.IncludeByDefault,
1061			}
1062			s.applyEndpointRoutingCost(&entry, pcfg, cat)
1063			entries = append(entries, entry)
1064		}
1065		return entries
1066	}
