1075	func snapshotEndpointName(pcfg ServiceProviderEntry, key snapshotProviderGroupKey) string {
1076		endpoints := modelDiscoveryEndpoints(pcfg)
1077		trimmedEndpointName := strings.TrimSpace(key.EndpointName)
1078		trimmedBaseURL := strings.TrimSpace(key.EndpointBaseURL)
1079		trimmedServerInstance := strings.TrimSpace(key.ServerInstance)
1080		if len(endpoints) == 0 {
1081			if trimmedEndpointName != "" {
1082				if strings.EqualFold(trimmedEndpointName, strings.TrimSpace(key.Provider)) {
1083					return "default"
1084				}
1085				return trimmedEndpointName
1086			}
1087			if trimmedServerInstance != "" {
1088				return trimmedServerInstance
1089			}
1090			if trimmedBaseURL != "" {
1091				return trimmedBaseURL
1092			}
1093			return ""
1094		}
1095		for _, endpoint := range endpoints {
1096			if trimmedEndpointName != "" && strings.EqualFold(endpoint.Name, trimmedEndpointName) {
1097				return endpoint.Name
1098			}
1099			if trimmedBaseURL != "" && strings.TrimSpace(endpoint.BaseURL) == trimmedBaseURL {
1100				return endpoint.Name
1101			}
1102			if trimmedServerInstance != "" && strings.TrimSpace(endpoint.ServerInstance) == trimmedServerInstance {
1103				return endpoint.Name
1104			}
1105		}
1106		if len(endpoints) == 1 {
1107			return endpoints[0].Name
1108		}
1109		if trimmedEndpointName != "" {
1110			return trimmedEndpointName
1111		}
1112		if trimmedServerInstance != "" {
1113			return trimmedServerInstance
1114		}
1115		if trimmedBaseURL != "" {
1116			return trimmedBaseURL
1117		}
1118		return ""
1119	}
