1142	func snapshotProviderContextWindows(ctx context.Context, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog, rows []modelsnapshot.KnownModel, discoveredIDs []string) (map[string]int, map[string]string) {
1143		_ = ctx
1144		out := make(map[string]int)
1145		sources := make(map[string]string)
1146		rowByID := make(map[string]modelsnapshot.KnownModel, len(rows))
1147		for _, row := range rows {
1148			id := strings.TrimSpace(row.ID)
1149			if id == "" {
1150				continue
1151			}
1152			if _, exists := rowByID[id]; !exists {
1153				rowByID[id] = row
1154			}
1155		}
1156		add := func(modelID string, snapshotWindow int) {
1157			modelID = strings.TrimSpace(modelID)
1158			if modelID == "" {
1159				return
1160			}
1161			window, source := snapshotContextWindow(pcfg, cat, modelID, snapshotWindow)
1162			if window <= 0 {
1163				return
1164			}
1165			out[modelID] = window
1166			sources[modelID] = source
1167		}
1168		if defaultModel := strings.TrimSpace(pcfg.Model); defaultModel != "" {
1169			row, ok := rowByID[defaultModel]
1170			if ok {
1171				add(defaultModel, row.ContextWindow)
1172			} else {
1173				add(defaultModel, 0)
1174			}
1175		}
1176		for _, id := range discoveredIDs {
1177			row, ok := rowByID[id]
1178			if ok {
1179				add(id, row.ContextWindow)
1180				continue
1181			}
1182			add(id, 0)
1183		}
1184		if len(out) == 0 {
1185			return nil, nil
1186		}
1187		return out, sources
1188	}
