1371	func serviceRoutingModelEligibility(entries []routing.HarnessEntry, cat *modelcatalog.Catalog) func(model string) (routing.ModelEligibility, bool) {
1372		if cat == nil {
1373			return nil
1374		}
1375		eligibility := make(map[string]routing.ModelEligibility)
1376		add := func(modelID string, includeByDefault bool, status string) {
1377			modelID = strings.TrimSpace(modelID)
1378			if modelID == "" {
1379				return
1380			}
1381			view := modeleligibility.Resolve(modelID, includeByDefault, status, cat)
1382			known := routing.ModelEligibility{
1383				Power:        view.Power,
1384				ExactPinOnly: view.ExactPinOnly,
1385				AutoRoutable: view.AutoRoutable,
1386			}
1387			if existing, ok := eligibility[modelID]; ok {
1388				if known.Power > existing.Power {
1389					existing.Power = known.Power
1390				}
1391				existing.ExactPinOnly = existing.ExactPinOnly || known.ExactPinOnly
1392				existing.AutoRoutable = existing.AutoRoutable || known.AutoRoutable
1393				eligibility[modelID] = existing
1394				return
1395			}
1396			eligibility[modelID] = known
1397		}
1398		for _, h := range entries {
1399			status := "available"
1400			if !h.Available {
1401				status = "unreachable"
1402			}
1403			if h.DefaultModel != "" {
1404				add(h.DefaultModel, true, status)
1405			}
1406			for _, modelID := range h.SupportedModels {
1407				add(modelID, true, status)
1408			}
1409			for _, p := range h.Providers {
1410				includeByDefault := !p.ExcludeFromDefaultRouting
1411				add(p.DefaultModel, includeByDefault, status)
1412				for _, modelID := range p.DiscoveredIDs {
1413					add(modelID, includeByDefault, status)
1414				}
1415			}
1416		}
1417		if len(eligibility) == 0 {
1418			return nil
1419		}
1420		return func(model string) (routing.ModelEligibility, bool) {
1421			known, ok := eligibility[strings.TrimSpace(model)]
1422			return known, ok
1423		}
1424	}
