1800	func subscriptionEffectiveCostUSDPer1kTokens(baseCost float64, quotaPercentUsed int, curve SubscriptionCostCurve) float64 {
1801		switch {
1802		case quotaPercentUsed <= curve.FreeUntilPercent:
1803			return 0
1804		case quotaPercentUsed <= curve.LowUntilPercent:
1805			return baseCost * curve.LowMultiplier
1806		case quotaPercentUsed <= curve.MediumUntilPercent:
1807			return baseCost * curve.MediumMultiplier
1808		default:
1809			return baseCost * curve.HighMultiplier
1810		}
